$ErrorActionPreference = 'Stop'
$repoRoot = [IO.Path]::GetFullPath($PSScriptRoot)
$planPath = Join-Path $repoRoot '.scratch/architecture-refactor-2026-10-18/qwen-finite-family/cleanup-plan.json'
$plan = Get-Content -LiteralPath $planPath -Raw | ConvertFrom-Json
if ($repoRoot -ne $plan.workspace) { throw 'Unexpected workspace' }
$allowedRoot = [IO.Path]::GetFullPath((Join-Path $repoRoot '.scratch/architecture-refactor-2026-10-18')) + [IO.Path]::DirectorySeparatorChar
function Assert-ExactFile($row) {
    $resolved = (Resolve-Path -LiteralPath $row.path).ProviderPath
    if (-not $resolved.StartsWith($allowedRoot, [StringComparison]::OrdinalIgnoreCase)) { throw "Outside workspace scratch: $resolved" }
    if ($resolved -ne [IO.Path]::GetFullPath($row.path)) { throw "Changed resolved path: $resolved" }
    $item = Get-Item -LiteralPath $resolved
    if ($item.PSIsContainer -or $item.Length -ne $row.bytes) { throw "Changed file size: $resolved" }
    if ((Get-FileHash -LiteralPath $resolved -Algorithm SHA256).Hash -ne $row.sha256) { throw "Changed file hash: $resolved" }
}
foreach ($row in $plan.delete) { Assert-ExactFile $row }
foreach ($row in $plan.protected) { Assert-ExactFile $row }
foreach ($row in $plan.delete) { Remove-Item -LiteralPath $row.path -Force }
foreach ($row in $plan.delete) { if (Test-Path -LiteralPath $row.path) { throw "Deletion incomplete: $($row.path)" } }
foreach ($row in $plan.protected) { Assert-ExactFile $row }
$receipt = [ordered]@{ status='executed'; files=$plan.target_count; reclaimed_bytes=$plan.target_bytes; protected_files=@($plan.protected).Count; exact_targets=$plan.delete; plan_sha256=(Get-FileHash -LiteralPath $planPath -Algorithm SHA256).Hash.ToLower(); finished_utc=[DateTime]::UtcNow.ToString('o') }
$receipt | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path (Split-Path -Parent $planPath) 'cleanup-executed.json') -Encoding utf8
Write-Output "CLEANUP_EXECUTED files=$($plan.target_count) bytes=$($plan.target_bytes)"
